<script setup>
import {router} from '@inertiajs/vue3'; import {computed} from 'vue'; import AppLayout from '../../../Layouts/AppLayout.vue'; import PaginationLinks from '../../../components/ui/PaginationLinks.vue';
const props=defineProps({report:String,entries:Object,accounts:Array,account:Object,lines:Array,opening:[String,Number],from:String,to:String,sections:Array,totals:Object,analytics:Array,trend:Array,journalSummary:Object,ledgerSummary:Object,trialSummary:Object});
const titles={journal:'Libro diario',ledger:'Libro mayor',trial:'Balance de comprobación','balance-sheet':'Balance general','income-statement':'Estado de resultados'};
const money=value=>new Intl.NumberFormat('es-NI',{style:'currency',currency:'NIO',minimumFractionDigits:2}).format(Number(value||0));
const go=(extra={})=>router.get(window.location.pathname,{date_from:props.from,date_to:props.to,...extra},{preserveState:true,replace:true});
const analyticsMax=computed(()=>Math.max(...(props.analytics||[]).map(item=>Math.abs(Number(item.value))),1));
const trendMax=computed(()=>Math.max(...(props.trend||[]).flatMap(item=>[Math.abs(Number(item.income)),Math.abs(Number(item.expenses))]),1));
</script>
<template><AppLayout :title="titles[report]" eyebrow="Reportes contables" description="Información generada exclusivamente desde movimientos contabilizados.">
 <div class="report-filter"><label v-if="report!=='balance-sheet'">Desde<input :value="from" type="date" @change="go({date_from:$event.target.value})"></label><label>Hasta<input :value="to" type="date" @change="go({date_to:$event.target.value})"></label><label v-if="report==='ledger'">Cuenta<select :value="account?.id||''" @change="go({account:$event.target.value})"><option value="">Seleccionar cuenta</option><option v-for="row in accounts" :key="row.id" :value="row.id">{{row.code}} · {{row.name}}</option></select></label></div>
 <section v-if="report==='balance-sheet'" class="statement-shell">
  <header><div><span>ESTADO FINANCIERO</span><h2>Situación financiera</h2><p>Al {{to}}</p></div><strong :class="Math.abs(Number(totals.assets)-Number(totals.liabilities_equity))<.01?'ok':'warn'">{{Math.abs(Number(totals.assets)-Number(totals.liabilities_equity))<.01?'Balance cuadrado':'Requiere revisión'}}</strong></header>
  <div class="analytics-zone"><div class="analytics-summary"><article><small>Utilidad neta acumulada</small><strong :class="Number(totals.current_result)>=0?'positive':'negative'">{{money(totals.current_result)}}</strong><p>Margen neto {{totals.net_margin}}%</p></article><article><small>Ingresos acumulados</small><strong>{{money(totals.income)}}</strong><p>Base del resultado</p></article><article><small>Gastos acumulados</small><strong>{{money(totals.expenses)}}</strong><p>{{totals.income?Math.round(Number(totals.expenses)/Number(totals.income)*100):0}}% de los ingresos</p></article></div><div class="structure-chart"><header><div><small>COMPOSICIÓN FINANCIERA</small><h3>Estructura del balance</h3></div></header><div v-for="item in analytics" :key="item.label" class="structure-row"><span>{{item.label}}</span><b>{{money(item.value)}}</b><div><i :style="{width:`${Math.max(2,Math.abs(Number(item.value))/analyticsMax*100)}%`,background:item.color}"></i></div></div></div></div>
  <div class="statement-grid"><article v-for="section in sections" :key="section.key" class="statement-section"><h3>{{section.label}}<b>{{money(section.accounts.reduce((sum,row)=>sum+Number(row.balance),0)+(section.key==='equity'?Number(totals.current_result):0))}}</b></h3><p v-for="row in section.accounts" :key="row.id"><span>{{row.code}} · {{row.name}}</span><b>{{money(row.balance)}}</b></p><p v-if="section.key==='equity'" class="result-line"><span>Resultado acumulado</span><b>{{money(totals.current_result)}}</b></p><p v-if="!section.accounts.length&&section.key!=='equity'" class="muted">Sin saldos</p></article></div>
  <footer><div><span>Total activos</span><strong>{{money(totals.assets)}}</strong></div><div><span>Pasivos + patrimonio</span><strong>{{money(totals.liabilities_equity)}}</strong></div></footer>
 </section>
 <section v-else-if="report==='income-statement'" class="statement-shell income">
  <header><div><span>RENDIMIENTO DEL PERÍODO</span><h2>Resultado operativo</h2><p>Del {{from}} al {{to}}</p></div><strong :class="Number(totals.result)>=0?'ok':'warn'">{{Number(totals.result)>=0?'Resultado positivo':'Resultado negativo'}}</strong></header>
  <div class="analytics-zone"><div class="analytics-summary"><article><small>Ingresos</small><strong>{{money(totals.income)}}</strong><p>Acumulados en el rango</p></article><article><small>Gastos</small><strong>{{money(totals.expenses)}}</strong><p>{{totals.income?Math.round(Number(totals.expenses)/Number(totals.income)*100):0}}% de ingresos</p></article><article><small>Utilidad neta</small><strong :class="Number(totals.result)>=0?'positive':'negative'">{{money(totals.result)}}</strong><p>Margen {{totals.margin}}%</p></article></div><div class="trend-chart"><header><div><small>EVOLUCIÓN MENSUAL</small><h3>Ingresos frente a gastos</h3></div><span><i></i>Ingresos <i></i>Gastos</span></header><div class="trend-bars"><div v-for="item in trend" :key="item.label" class="trend-month" :title="`${item.label}: resultado ${money(item.result)}`"><div><i :style="{height:`${Math.max(3,Number(item.income)/trendMax*100)}%`}"></i><i :style="{height:`${Math.max(3,Number(item.expenses)/trendMax*100)}%`}"></i></div><small>{{item.label.split(' ')[0]}}</small></div></div></div></div>
  <div class="statement-grid"><article v-for="section in sections" :key="section.key" class="statement-section"><h3>{{section.label}}<b>{{money(section.accounts.reduce((sum,row)=>sum+Number(row.balance),0))}}</b></h3><p v-for="row in section.accounts" :key="row.id"><span>{{row.code}} · {{row.name}}</span><b>{{money(row.balance)}}</b></p><p v-if="!section.accounts.length" class="muted">Sin movimientos</p></article></div>
  <footer class="result-footer"><div><span>Resultado neto del período</span><strong>{{money(totals.result)}}</strong></div></footer>
 </section>
 <template v-else><section class="report-kpis"><article v-if="report==='journal'"><small>Asientos del rango</small><strong>{{journalSummary.entries}}</strong><p>{{money(journalSummary.movement)}} movilizados</p></article><article v-if="report==='journal'"><small>Reversiones</small><strong>{{journalSummary.reversals}}</strong><p>Conservadas en el libro</p></article><article v-if="report==='ledger'"><small>Saldo inicial</small><strong>{{money(opening)}}</strong><p>Antes del rango</p></article><article v-if="report==='ledger'"><small>Saldo final</small><strong>{{money(ledgerSummary.closing)}}</strong><p>{{money(ledgerSummary.debit)}} debe · {{money(ledgerSummary.credit)}} haber</p></article><article v-if="report==='trial'"><small>Total debe</small><strong>{{money(trialSummary.debit)}}</strong><p>Movimientos del rango</p></article><article v-if="report==='trial'"><small>Total haber</small><strong>{{money(trialSummary.credit)}}</strong><p>Diferencia {{money(trialSummary.difference)}}</p></article></section><section class="card overflow-hidden">
  <div v-if="report==='journal'" class="divide-y"><div v-for="entry in entries.data" :key="entry.id" class="p-5"><p class="text-base font-semibold">{{entry.number}} · {{entry.concept}}</p><p class="text-sm text-slate-400">{{entry.date}}</p><div class="mt-2 text-sm" v-for="line in entry.lines" :key="line.id">{{line.account.code}} · Debe {{money(line.debit)}} · Haber {{money(line.credit)}}</div></div><PaginationLinks :links="entries.links"/></div>
  <div v-else-if="report==='ledger'" class="p-5"><p v-if="account" class="mb-4 text-base font-semibold">{{account.code}} · {{account.name}}</p><div v-for="line in lines" :key="line.id" class="ledger-row"><span>{{line.journal_entry.date}}</span><span>{{line.journal_entry.number}}</span><span>Debe {{money(line.debit)}}</span><span>Haber {{money(line.credit)}}</span><strong>Saldo {{money(line.running_balance)}}</strong></div><p v-if="!account" class="empty-state">Selecciona una cuenta.</p></div>
  <div v-else class="table-wrap"><table class="w-full"><thead><tr><th class="table-cell">Cuenta</th><th class="table-cell text-right">Debe</th><th class="table-cell text-right">Haber</th></tr></thead><tbody><tr v-for="row in accounts" :key="row.id"><td class="table-cell text-sm">{{row.code}} · {{row.name}}</td><td class="table-cell text-right text-sm">{{money(row.debit||0)}}</td><td class="table-cell text-right text-sm">{{money(row.credit||0)}}</td></tr></tbody></table></div>
 </section></template>
</AppLayout></template>
<style scoped>
.report-filter{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:1rem;border:1px solid #dfe8e8;border-radius:1.1rem;background:#fff;padding:1rem}.report-filter label{display:grid;gap:.35rem;color:#60737c;font-size:.72rem;font-weight:800}.report-filter input,.report-filter select{height:2.8rem;min-width:12rem;border:1px solid #d8e3e4;border-radius:.75rem;background:#f8fafb;padding:0 .8rem;color:#183943;font-size:.85rem}.statement-shell{overflow:hidden;border:1px solid #d9e5e4;border-radius:1.35rem;background:#fff;box-shadow:0 10px 30px rgba(11,61,65,.07)}.statement-shell>header{display:flex;align-items:center;justify-content:space-between;gap:1rem;background:linear-gradient(135deg,#103f43,#092d39);padding:1.4rem 1.6rem;color:#fff}.statement-shell header span{color:#6ee7d0;font-size:.66rem;font-weight:800;letter-spacing:.14em}.statement-shell header h2{margin-top:.2rem;font-size:1.35rem;font-weight:800}.statement-shell header p{color:#a7c0c5;font-size:.78rem}.statement-shell header>strong{border-radius:999px;padding:.45rem .7rem;font-size:.72rem}.statement-shell header>strong.ok{background:rgba(52,211,153,.15);color:#69e4b7}.statement-shell header>strong.warn{background:rgba(246,196,83,.16);color:#f6c453}.statement-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;padding:1rem}.income .statement-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.statement-section{border:1px solid #e2eaea;border-radius:1rem;padding:1rem}.statement-section h3{display:flex;justify-content:space-between;gap:1rem;border-bottom:2px solid #0d8075;padding-bottom:.75rem;color:#173b44;font-size:.95rem;font-weight:800}.statement-section h3 b{color:#08756c}.statement-section p{display:flex;justify-content:space-between;gap:1rem;border-bottom:1px solid #edf2f2;padding:.75rem .2rem;color:#526870;font-size:.82rem}.statement-section p b{color:#173b44}.statement-section .result-line{margin-top:.4rem;background:#eef8f5;font-weight:800}.statement-section .muted{color:#9aa8ad}.statement-shell>footer{display:grid;grid-template-columns:1fr 1fr;gap:1rem;background:#f4f8f7;padding:1rem}.statement-shell footer div{display:flex;align-items:center;justify-content:space-between;border-radius:.9rem;background:#fff;padding:1rem 1.2rem;color:#49626a;font-size:.85rem;font-weight:700}.statement-shell footer strong{color:#0a655e;font-size:1.15rem}.statement-shell>.result-footer{grid-template-columns:1fr}.result-footer div{background:#0d756d;color:#d9f2ed}.result-footer strong{color:#fff;font-size:1.35rem}@media(max-width:900px){.statement-grid,.income .statement-grid{grid-template-columns:1fr}.statement-shell>footer{grid-template-columns:1fr}}@media(max-width:600px){.statement-shell>header{align-items:flex-start;flex-direction:column}.report-filter label,.report-filter input,.report-filter select{width:100%}.statement-shell>footer{padding:.75rem}}
.analytics-zone{display:grid;grid-template-columns:minmax(0,.8fr) minmax(22rem,1.2fr);gap:1rem;background:#f4f8f7;padding:1rem}.analytics-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.analytics-summary article,.structure-chart,.trend-chart{border:1px solid #dfe9e7;border-radius:1rem;background:#fff;padding:1rem}.analytics-summary small{color:#70858c;font-size:.68rem;font-weight:800}.analytics-summary strong{display:block;margin-top:.45rem;color:#173b44;font-size:1.1rem}.analytics-summary strong.positive{color:#08775f}.analytics-summary strong.negative{color:#c64358}.analytics-summary p{margin-top:.2rem;color:#91a0a5;font-size:.6rem}.structure-chart>header,.trend-chart>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:.8rem}.structure-chart header small,.trend-chart header small{color:#087a70;font-size:.58rem;font-weight:800;letter-spacing:.12em}.structure-chart header h3,.trend-chart header h3{color:#173b44;font-size:.9rem;font-weight:800}.structure-row{display:grid;grid-template-columns:1fr auto;gap:.35rem .75rem;margin-top:.65rem;color:#587078;font-size:.68rem}.structure-row>b{color:#173b44}.structure-row>div{grid-column:1/-1;height:.5rem;overflow:hidden;border-radius:999px;background:#edf2f2}.structure-row i{display:block;height:100%;border-radius:999px}.trend-chart header>span{display:flex;align-items:center;gap:.35rem;color:#778a91;font-size:.58rem}.trend-chart header>span i{width:.5rem;height:.5rem;border-radius:50%;background:#0b9b82}.trend-chart header>span i:last-of-type{background:#f0a51a}.trend-bars{display:flex;align-items:flex-end;gap:.5rem;height:8rem;border-bottom:1px solid #dce5e5}.trend-month{display:flex;flex:1;min-width:1.5rem;height:100%;align-items:flex-end;justify-content:center;position:relative}.trend-month>div{display:flex;width:80%;height:100%;align-items:flex-end;justify-content:center;gap:2px}.trend-month i{width:45%;min-height:3px;border-radius:.3rem .3rem 0 0;background:#0b9b82}.trend-month i:last-child{background:#f0a51a}.trend-month small{position:absolute;top:calc(100% + .25rem);color:#839299;font-size:.52rem}.report-kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem;margin-bottom:1rem}.report-kpis article{border:1px solid #dfe8e8;border-radius:1rem;background:#fff;padding:1rem 1.2rem}.report-kpis small{color:#70848b;font-size:.7rem;font-weight:800}.report-kpis strong{display:block;margin-top:.3rem;color:#113b45;font-size:1.3rem}.report-kpis p{color:#91a0a5;font-size:.65rem}.ledger-row{display:grid;grid-template-columns:7rem 8rem 1fr 1fr 1fr;gap:.8rem;border-bottom:1px solid #e8eeee;padding:.8rem 0;color:#5d727a;font-size:.78rem}.ledger-row strong{text-align:right;color:#0b6f67}@media(max-width:1100px){.analytics-zone{grid-template-columns:1fr}}@media(max-width:720px){.analytics-summary{grid-template-columns:1fr}.ledger-row{grid-template-columns:1fr 1fr}.ledger-row strong{grid-column:1/-1;text-align:left}}@media(max-width:500px){.report-kpis{grid-template-columns:1fr}.trend-chart header{align-items:flex-start;flex-direction:column;gap:.5rem}}
</style>
